//! URLCORE (LEDGER SR87) — the WHATWG URL Standard (url.spec.whatwg.org), `no_std` + `alloc`, no dependencies:
//!
//! * the basic URL parser (§4.4) with every state and the state overrides the setters use;
//! * hosts (§3): the host parser with IPv4 / IPv6 / opaque hosts, and "domain to ASCII" through UTS #46
//!   ([`idna`]: the IDNA Mapping Table, NFC, the validity criteria with CheckBidi and CheckJoiners, Punycode —
//!   the Unicode data generated by `tools/gen_idna.py`);
//! * the serializers (§3.6, §4.5) and origins (§4.7);
//! * the percent-encode sets (§1.3, [`percent`]);
//! * the `URL` API (§6.1): every getter, every setter with its re-parse semantics, `URL.parse`/`URL.canParse`;
//! * application/x-www-form-urlencoded and `URLSearchParams` (§5, §6.2, [`form`]).
//!
//! Proof: WPT `url/resources/urltestdata.json`, `setters_tests.json`, `toascii.json` and `IdnaTestV2.json`
//! (tests/url_wpt.rs, which reads them from `$UNAOS_WPT_DIR/url/resources/`).
//!
//! ```
//! use html_core::url::Url;
//! let base = Url::parse("https://EXAMPLE.com/a/b?x#y").unwrap();
//! let mut u = base.join("../c d?q=1").unwrap();
//! assert_eq!(u.href(), "https://example.com/c%20d?q=1");
//! u.set_hostname("b\u{FC}cher.de");
//! u.set_port("8443");
//! assert_eq!(u.host_str(), "xn--bcher-kva.de:8443");
//! assert_eq!(u.origin(), "https://xn--bcher-kva.de:8443");
//! ```

pub mod form;
pub mod host;
pub mod idna;
#[rustfmt::skip]
mod idna_tables;
pub mod percent;

use alloc::format;
use alloc::string::{String, ToString};
use alloc::vec::Vec;
use core::fmt;

pub use form::UrlSearchParams;
pub use host::{parse_host, parse_ipv4, parse_ipv6, Host};
pub use idna::{punycode_decode, punycode_encode};
pub use percent::{percent_decode, percent_decode_str, percent_encode, percent_encode_into, EncodeSet};

/// A parse failure (the standard's "failure"; validation errors that are not fatal are not reported).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UrlError {
    /// No scheme and no base (or a base with an opaque path).
    MissingSchemeNonRelative,
    /// `https://` with no host, `http://user@/`, an empty host in a special URL.
    HostMissing,
    /// A host that failed the host parser (forbidden code point, bad IPv4/IPv6, IDNA failure).
    InvalidHost,
    /// A port that is not decimal or exceeds 65535.
    InvalidPort,
    /// A scheme that does not start with an ASCII alpha or holds a code point outside [A-Za-z0-9+.-]
    /// (reachable only through the `protocol` setter's state override).
    InvalidScheme,
}

impl fmt::Display for UrlError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            UrlError::MissingSchemeNonRelative => "relative URL without a base",
            UrlError::HostMissing => "missing host",
            UrlError::InvalidHost => "invalid host",
            UrlError::InvalidPort => "invalid port",
            UrlError::InvalidScheme => "invalid scheme",
        })
    }
}

/// §3.3 domain to ASCII with beStrict = false (the URL parser's call).
pub fn domain_to_ascii(domain: &str) -> Result<String, UrlError> {
    idna::domain_to_ascii(domain, false)
}

/// A URL's path: an opaque string (`mailto:x`) or a list of segments.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum UrlPath {
    Opaque(String),
    List(Vec<String>),
}

/// §4.1 a URL record.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Url {
    scheme: String,
    username: String,
    password: String,
    host: Option<Host>,
    port: Option<u16>,
    path: UrlPath,
    query: Option<String>,
    fragment: Option<String>,
}

/// §4.2 special schemes and their default ports.
pub fn default_port(scheme: &str) -> Option<u16> {
    match scheme {
        "ftp" => Some(21),
        "http" | "ws" => Some(80),
        "https" | "wss" => Some(443),
        _ => None,
    }
}

/// §4.2 a special scheme.
pub fn is_special(scheme: &str) -> bool {
    matches!(scheme, "ftp" | "file" | "http" | "https" | "ws" | "wss")
}

// ---------------------------------------------------------------- §4.4 the basic URL parser

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum State {
    SchemeStart,
    Scheme,
    NoScheme,
    SpecialRelativeOrAuthority,
    PathOrAuthority,
    Relative,
    RelativeSlash,
    SpecialAuthoritySlashes,
    SpecialAuthorityIgnoreSlashes,
    Authority,
    Host,
    Hostname,
    Port,
    File,
    FileSlash,
    FileHost,
    PathStart,
    Path,
    OpaquePath,
    Query,
    Fragment,
}

fn is_wdl(a: char, b: char) -> bool {
    a.is_ascii_alphabetic() && (b == ':' || b == '|')
}

/// §4.3 a Windows drive letter (`normalized`: the second code point must be `:`).
fn is_windows_drive_letter(s: &str, normalized: bool) -> bool {
    let mut it = s.chars();
    match (it.next(), it.next(), it.next()) {
        (Some(a), Some(b), None) => a.is_ascii_alphabetic() && (b == ':' || (!normalized && b == '|')),
        _ => false,
    }
}

/// §4.3 "starts with a Windows drive letter".
fn starts_with_wdl(c: &[char]) -> bool {
    c.len() >= 2 && is_wdl(c[0], c[1]) && (c.len() == 2 || matches!(c[2], '/' | '\\' | '?' | '#'))
}

fn single_dot(s: &str) -> bool {
    s == "." || s.eq_ignore_ascii_case("%2e")
}

fn double_dot(s: &str) -> bool {
    s == ".." || s.eq_ignore_ascii_case(".%2e") || s.eq_ignore_ascii_case("%2e.") || s.eq_ignore_ascii_case("%2e%2e")
}

fn strip_tab_newline(input: &str) -> Vec<char> {
    input.chars().filter(|&c| c != '\t' && c != '\n' && c != '\r').collect()
}

impl Url {
    fn empty() -> Url {
        Url {
            scheme: String::new(),
            username: String::new(),
            password: String::new(),
            host: None,
            port: None,
            path: UrlPath::List(Vec::new()),
            query: None,
            fragment: None,
        }
    }

    /// Parse `input` with no base.
    pub fn parse(input: &str) -> Result<Url, UrlError> {
        Self::parse_with_base(input, None)
    }

    /// Join `input` against this URL (the standard's "parse with base").
    pub fn join(&self, input: &str) -> Result<Url, UrlError> {
        Self::parse_with_base(input, Some(self))
    }

    /// The basic URL parser with no URL and no state override (UTF-8 encoding): leading and trailing C0
    /// controls and spaces are removed, then every ASCII tab or newline.
    pub fn parse_with_base(input: &str, base: Option<&Url>) -> Result<Url, UrlError> {
        let trimmed = input.trim_matches(|c: char| (c as u32) <= 0x20);
        let chars = strip_tab_newline(trimmed);
        let mut url = Url::empty();
        url.run(&chars, base, None)?;
        Ok(url)
    }

    /// §6.1 the API URL parser as `new URL(url, base)` / `URL.parse` run it: the base string is parsed first
    /// and its failure is a failure.
    pub fn parse_str_with_base(input: &str, base: Option<&str>) -> Result<Url, UrlError> {
        match base {
            None => Url::parse(input),
            Some(b) => Url::parse(b)?.join(input),
        }
    }

    /// `URL.canParse(url, base)`.
    pub fn can_parse(input: &str, base: Option<&str>) -> bool {
        Self::parse_str_with_base(input, base).is_ok()
    }

    /// Run the basic URL parser over this URL with `state` as the state override (a setter); the result is
    /// ignored, as every setter ignores it — what the parser set before a failure stays set.
    fn reparse(&mut self, input: &str, state: State) {
        let chars = strip_tab_newline(input);
        let _ = self.run(&chars, None, Some(state));
    }

    /// The state machine. `so` is the state override; `Ok(())` is both "return" and running off the end.
    fn run(&mut self, chars: &[char], base: Option<&Url>, so: Option<State>) -> Result<(), UrlError> {
        let mut state = so.unwrap_or(State::SchemeStart);
        let mut buffer = String::new();
        let (mut at_sign_seen, mut inside_brackets, mut password_token_seen) = (false, false, false);
        let n = chars.len() as isize;
        let mut p: isize = 0;
        loop {
            let c: Option<char> = if p >= 0 && p < n { Some(chars[p as usize]) } else { None };
            let rest = |p: isize| -> &[char] {
                let i = (p + 1).max(0) as usize;
                if i <= chars.len() { &chars[i..] } else { &[] }
            };
            let from = |p: isize| -> &[char] {
                let i = p.max(0) as usize;
                if i <= chars.len() { &chars[i..] } else { &[] }
            };
            let special = is_special(&self.scheme);
            let ends_authority = |c: Option<char>| matches!(c, None | Some('/') | Some('?') | Some('#')) || (special && c == Some('\\'));
            match state {
                State::SchemeStart => match c {
                    Some(ch) if ch.is_ascii_alphabetic() => {
                        buffer.push(ch.to_ascii_lowercase());
                        state = State::Scheme;
                    }
                    _ if so.is_none() => {
                        state = State::NoScheme;
                        p -= 1;
                    }
                    _ => return Err(UrlError::InvalidScheme),
                },
                State::Scheme => match c {
                    Some(ch) if ch.is_ascii_alphanumeric() || matches!(ch, '+' | '-' | '.') => {
                        buffer.push(ch.to_ascii_lowercase())
                    }
                    Some(':') => {
                        if so.is_some() {
                            if special != is_special(&buffer) {
                                return Ok(());
                            }
                            if (self.includes_credentials() || self.port.is_some()) && buffer == "file" {
                                return Ok(());
                            }
                            if self.scheme == "file" && self.host == Some(Host::Empty) {
                                return Ok(());
                            }
                        }
                        self.scheme = core::mem::take(&mut buffer);
                        if so.is_some() {
                            if self.port.is_some() && self.port == default_port(&self.scheme) {
                                self.port = None;
                            }
                            return Ok(());
                        }
                        if self.scheme == "file" {
                            state = State::File;
                        } else if is_special(&self.scheme) && base.is_some_and(|b| b.scheme == self.scheme) {
                            state = State::SpecialRelativeOrAuthority;
                        } else if is_special(&self.scheme) {
                            state = State::SpecialAuthoritySlashes;
                        } else if rest(p).first() == Some(&'/') {
                            state = State::PathOrAuthority;
                            p += 1;
                        } else {
                            self.path = UrlPath::Opaque(String::new());
                            state = State::OpaquePath;
                        }
                    }
                    _ if so.is_none() => {
                        buffer.clear();
                        state = State::NoScheme;
                        p = -1;
                    }
                    _ => return Err(UrlError::InvalidScheme),
                },
                State::NoScheme => {
                    let Some(b) = base else { return Err(UrlError::MissingSchemeNonRelative) };
                    let opaque = matches!(b.path, UrlPath::Opaque(_));
                    if opaque && c != Some('#') {
                        return Err(UrlError::MissingSchemeNonRelative);
                    } else if opaque {
                        self.scheme = b.scheme.clone();
                        self.path = b.path.clone();
                        self.query = b.query.clone();
                        self.fragment = Some(String::new());
                        state = State::Fragment;
                    } else if b.scheme != "file" {
                        state = State::Relative;
                        p -= 1;
                    } else {
                        state = State::File;
                        p -= 1;
                    }
                }
                State::SpecialRelativeOrAuthority => {
                    if c == Some('/') && rest(p).first() == Some(&'/') {
                        state = State::SpecialAuthorityIgnoreSlashes;
                        p += 1;
                    } else {
                        state = State::Relative;
                        p -= 1;
                    }
                }
                State::PathOrAuthority => {
                    if c == Some('/') {
                        state = State::Authority;
                    } else {
                        state = State::Path;
                        p -= 1;
                    }
                }
                State::Relative => {
                    let Some(b) = base else { return Err(UrlError::MissingSchemeNonRelative) };
                    self.scheme = b.scheme.clone();
                    let special = is_special(&self.scheme);
                    if c == Some('/') || (special && c == Some('\\')) {
                        state = State::RelativeSlash;
                    } else {
                        self.username = b.username.clone();
                        self.password = b.password.clone();
                        self.host = b.host.clone();
                        self.port = b.port;
                        self.path = b.path.clone();
                        self.query = b.query.clone();
                        match c {
                            Some('?') => {
                                self.query = Some(String::new());
                                state = State::Query;
                            }
                            Some('#') => {
                                self.fragment = Some(String::new());
                                state = State::Fragment;
                            }
                            Some(_) => {
                                self.query = None;
                                self.shorten_path();
                                state = State::Path;
                                p -= 1;
                            }
                            None => {}
                        }
                    }
                }
                State::RelativeSlash => {
                    if special && (c == Some('/') || c == Some('\\')) {
                        state = State::SpecialAuthorityIgnoreSlashes;
                    } else if c == Some('/') {
                        state = State::Authority;
                    } else {
                        let Some(b) = base else { return Err(UrlError::MissingSchemeNonRelative) };
                        self.username = b.username.clone();
                        self.password = b.password.clone();
                        self.host = b.host.clone();
                        self.port = b.port;
                        state = State::Path;
                        p -= 1;
                    }
                }
                State::SpecialAuthoritySlashes => {
                    state = State::SpecialAuthorityIgnoreSlashes;
                    if c == Some('/') && rest(p).first() == Some(&'/') {
                        p += 1;
                    } else {
                        p -= 1;
                    }
                }
                State::SpecialAuthorityIgnoreSlashes => {
                    if c != Some('/') && c != Some('\\') {
                        state = State::Authority;
                        p -= 1;
                    }
                }
                State::Authority => {
                    if c == Some('@') {
                        if at_sign_seen {
                            buffer.insert_str(0, "%40");
                        }
                        at_sign_seen = true;
                        for cp in buffer.chars() {
                            if cp == ':' && !password_token_seen {
                                password_token_seen = true;
                                continue;
                            }
                            let target = if password_token_seen { &mut self.password } else { &mut self.username };
                            percent::push_char_encoded(target, cp, EncodeSet::Userinfo);
                        }
                        buffer.clear();
                    } else if ends_authority(c) {
                        if at_sign_seen && buffer.is_empty() {
                            return Err(UrlError::HostMissing);
                        }
                        p -= buffer.chars().count() as isize + 1;
                        buffer.clear();
                        state = State::Host;
                    } else if let Some(ch) = c {
                        buffer.push(ch);
                    }
                }
                State::Host | State::Hostname => {
                    if so.is_some() && self.scheme == "file" {
                        p -= 1;
                        state = State::FileHost;
                    } else if c == Some(':') && !inside_brackets {
                        if buffer.is_empty() {
                            return Err(UrlError::HostMissing);
                        }
                        if so == Some(State::Hostname) {
                            return Err(UrlError::InvalidHost);
                        }
                        self.host = Some(parse_host(&buffer, !special)?);
                        buffer.clear();
                        state = State::Port;
                    } else if ends_authority(c) {
                        p -= 1;
                        if special && buffer.is_empty() {
                            return Err(UrlError::HostMissing);
                        } else if so.is_some()
                            && buffer.is_empty()
                            && (self.includes_credentials() || self.port.is_some())
                        {
                            return Err(UrlError::HostMissing);
                        }
                        self.host = Some(if buffer.is_empty() { Host::Empty } else { parse_host(&buffer, !special)? });
                        buffer.clear();
                        state = State::PathStart;
                        if so.is_some() {
                            return Ok(());
                        }
                    } else if let Some(ch) = c {
                        if ch == '[' {
                            inside_brackets = true;
                        }
                        if ch == ']' {
                            inside_brackets = false;
                        }
                        buffer.push(ch);
                    }
                }
                State::Port => match c {
                    Some(ch) if ch.is_ascii_digit() => buffer.push(ch),
                    _ if ends_authority(c) || so.is_some() => {
                        if !buffer.is_empty() {
                            let mut port: u32 = 0;
                            for b in buffer.bytes() {
                                port = port * 10 + (b - b'0') as u32;
                                if port > 65535 {
                                    return Err(UrlError::InvalidPort);
                                }
                            }
                            let port = port as u16;
                            self.port = if default_port(&self.scheme) == Some(port) { None } else { Some(port) };
                            buffer.clear();
                            if so.is_some() {
                                return Ok(());
                            }
                        }
                        if so.is_some() {
                            return Err(UrlError::InvalidPort);
                        }
                        state = State::PathStart;
                        p -= 1;
                    }
                    _ => return Err(UrlError::InvalidPort),
                },
                State::File => {
                    self.scheme = "file".to_string();
                    self.host = Some(Host::Empty);
                    if c == Some('/') || c == Some('\\') {
                        state = State::FileSlash;
                    } else if let Some(b) = base.filter(|b| b.scheme == "file") {
                        self.host = b.host.clone();
                        self.path = b.path.clone();
                        self.query = b.query.clone();
                        match c {
                            Some('?') => {
                                self.query = Some(String::new());
                                state = State::Query;
                            }
                            Some('#') => {
                                self.fragment = Some(String::new());
                                state = State::Fragment;
                            }
                            Some(_) => {
                                self.query = None;
                                if !starts_with_wdl(from(p)) {
                                    self.shorten_path();
                                } else {
                                    self.path = UrlPath::List(Vec::new());
                                }
                                state = State::Path;
                                p -= 1;
                            }
                            None => {}
                        }
                    } else {
                        state = State::Path;
                        p -= 1;
                    }
                }
                State::FileSlash => {
                    if c == Some('/') || c == Some('\\') {
                        state = State::FileHost;
                    } else {
                        if let Some(b) = base.filter(|b| b.scheme == "file") {
                            self.host = b.host.clone();
                            if !starts_with_wdl(from(p)) {
                                if let UrlPath::List(bp) = &b.path {
                                    if let Some(first) = bp.first().filter(|s| is_windows_drive_letter(s, true)) {
                                        self.path_list().push(first.clone());
                                    }
                                }
                            }
                        }
                        state = State::Path;
                        p -= 1;
                    }
                }
                State::FileHost => {
                    if matches!(c, None | Some('/') | Some('\\') | Some('?') | Some('#')) {
                        p -= 1;
                        if so.is_none() && is_windows_drive_letter(&buffer, false) {
                            // The Windows drive letter quirk: buffer is not reset, the path state uses it.
                            state = State::Path;
                        } else if buffer.is_empty() {
                            self.host = Some(Host::Empty);
                            if so.is_some() {
                                return Ok(());
                            }
                            state = State::PathStart;
                        } else {
                            let mut host = parse_host(&buffer, !special)?;
                            if host == Host::Domain("localhost".into()) {
                                host = Host::Empty;
                            }
                            self.host = Some(host);
                            if so.is_some() {
                                return Ok(());
                            }
                            buffer.clear();
                            state = State::PathStart;
                        }
                    } else if let Some(ch) = c {
                        buffer.push(ch);
                    }
                }
                State::PathStart => {
                    if special {
                        state = State::Path;
                        if c != Some('/') && c != Some('\\') {
                            p -= 1;
                        }
                    } else if so.is_none() && c == Some('?') {
                        self.query = Some(String::new());
                        state = State::Query;
                    } else if so.is_none() && c == Some('#') {
                        self.fragment = Some(String::new());
                        state = State::Fragment;
                    } else if c.is_some() {
                        state = State::Path;
                        if c != Some('/') {
                            p -= 1;
                        }
                    } else if so.is_some() && self.host.is_none() {
                        self.path_list().push(String::new());
                    }
                }
                State::Path => {
                    let slashish = c == Some('/') || (special && c == Some('\\'));
                    if c.is_none() || slashish || (so.is_none() && matches!(c, Some('?') | Some('#'))) {
                        if double_dot(&buffer) {
                            self.shorten_path();
                            if !slashish {
                                self.path_list().push(String::new());
                            }
                        } else if single_dot(&buffer) && !slashish {
                            self.path_list().push(String::new());
                        } else if !single_dot(&buffer) {
                            if self.scheme == "file" && self.path_list().is_empty() && is_windows_drive_letter(&buffer, false) {
                                let first = buffer.chars().next().unwrap_or('c');
                                buffer = format!("{first}:");
                            }
                            self.path_list().push(core::mem::take(&mut buffer));
                        }
                        buffer.clear();
                        if c == Some('?') {
                            self.query = Some(String::new());
                            state = State::Query;
                        }
                        if c == Some('#') {
                            self.fragment = Some(String::new());
                            state = State::Fragment;
                        }
                    } else if let Some(ch) = c {
                        percent::push_char_encoded(&mut buffer, ch, EncodeSet::Path);
                    }
                }
                State::OpaquePath => {
                    match c {
                        Some('?') => {
                            self.query = Some(String::new());
                            state = State::Query;
                        }
                        Some('#') => {
                            self.fragment = Some(String::new());
                            state = State::Fragment;
                        }
                        Some(ch) => {
                            let next_ends = matches!(rest(p).first(), Some('?') | Some('#'));
                            if let UrlPath::Opaque(s) = &mut self.path {
                                if ch == ' ' {
                                    s.push_str(if next_ends { "%20" } else { " " });
                                } else {
                                    percent::push_char_encoded(s, ch, EncodeSet::C0Control);
                                }
                            }
                        }
                        None => {}
                    }
                }
                State::Query => {
                    if (so.is_none() && c == Some('#')) || c.is_none() {
                        let set = if special { EncodeSet::SpecialQuery } else { EncodeSet::Query };
                        let q = self.query.get_or_insert_with(String::new);
                        percent_encode_into(q, &buffer, set);
                        buffer.clear();
                        if c == Some('#') {
                            self.fragment = Some(String::new());
                            state = State::Fragment;
                        }
                    } else if let Some(ch) = c {
                        buffer.push(ch);
                    }
                }
                State::Fragment => {
                    if let Some(ch) = c {
                        percent::push_char_encoded(self.fragment.get_or_insert_with(String::new), ch, EncodeSet::Fragment);
                    }
                }
            }
            if p >= n {
                break;
            }
            p += 1;
        }
        Ok(())
    }

    fn path_list(&mut self) -> &mut Vec<String> {
        if let UrlPath::Opaque(_) = self.path {
            self.path = UrlPath::List(Vec::new());
        }
        match &mut self.path {
            UrlPath::List(v) => v,
            UrlPath::Opaque(_) => unreachable!(),
        }
    }

    /// §4.1 shorten a URL's path.
    fn shorten_path(&mut self) {
        let file = self.scheme == "file";
        if let UrlPath::List(v) = &mut self.path {
            if file && v.len() == 1 && is_windows_drive_letter(&v[0], true) {
                return;
            }
            v.pop();
        }
    }

    // ------------------------------------------------------------ §4.1 predicates

    /// The URL includes credentials (a non-empty username or password).
    pub fn includes_credentials(&self) -> bool {
        !self.username.is_empty() || !self.password.is_empty()
    }

    /// The URL cannot have a username/password/port: its host is null or empty, or its scheme is `file`.
    pub fn cannot_have_username_password_port(&self) -> bool {
        matches!(self.host, None | Some(Host::Empty)) || self.scheme == "file"
    }

    /// The URL has an opaque path.
    pub fn has_opaque_path(&self) -> bool {
        matches!(self.path, UrlPath::Opaque(_))
    }

    // ------------------------------------------------------------ record accessors

    pub fn scheme(&self) -> &str {
        &self.scheme
    }
    pub fn username(&self) -> &str {
        &self.username
    }
    pub fn password(&self) -> &str {
        &self.password
    }
    pub fn host(&self) -> Option<&Host> {
        self.host.as_ref()
    }
    /// The port as written (None when absent or the scheme's default).
    pub fn port(&self) -> Option<u16> {
        self.port
    }
    /// The port, or the scheme's default.
    pub fn port_or_default(&self) -> Option<u16> {
        self.port.or_else(|| default_port(&self.scheme))
    }
    pub fn is_special(&self) -> bool {
        is_special(&self.scheme)
    }
    pub fn path(&self) -> &UrlPath {
        &self.path
    }
    pub fn query(&self) -> Option<&str> {
        self.query.as_deref()
    }
    pub fn fragment(&self) -> Option<&str> {
        self.fragment.as_deref()
    }

    /// Set the fragment directly: `None` removes it, `Some` is percent-encoded with the fragment set.
    pub fn set_fragment(&mut self, f: Option<&str>) {
        self.fragment = f.map(|s| percent_encode(s, EncodeSet::Fragment));
    }

    /// Set the query directly: `None` removes it; `Some(q)` makes it `q` run through the query state (so
    /// `Some("")` is a present, empty query — `?` — unlike the `search` setter).
    pub fn set_query(&mut self, q: Option<&str>) {
        match q {
            None => self.query = None,
            Some(q) => {
                self.query = Some(String::new());
                self.reparse(q, State::Query);
            }
        }
    }

    // ------------------------------------------------------------ §6.1 the URL API: getters

    /// `href` (§4.5 the URL serializer).
    pub fn href(&self) -> String {
        self.serialize(false)
    }
    /// `protocol`.
    pub fn protocol(&self) -> String {
        format!("{}:", self.scheme)
    }
    /// `hostname`.
    pub fn hostname(&self) -> String {
        self.host.as_ref().map(|h| h.to_string()).unwrap_or_default()
    }
    /// `host` (hostname[:port]).
    pub fn host_str(&self) -> String {
        match (&self.host, self.port) {
            (None, _) => String::new(),
            (Some(h), None) => h.to_string(),
            (Some(h), Some(p)) => format!("{h}:{p}"),
        }
    }
    /// `port` as the API returns it: the empty string when null.
    pub fn port_str(&self) -> String {
        self.port.map(|p| p.to_string()).unwrap_or_default()
    }
    /// `pathname` (§4.5 URL path serializer).
    pub fn pathname(&self) -> String {
        match &self.path {
            UrlPath::Opaque(s) => s.clone(),
            UrlPath::List(v) => {
                let mut o = String::new();
                for seg in v {
                    o.push('/');
                    o.push_str(seg);
                }
                o
            }
        }
    }
    /// `search`.
    pub fn search(&self) -> String {
        match self.query.as_deref() {
            None | Some("") => String::new(),
            Some(q) => format!("?{q}"),
        }
    }
    /// `hash`.
    pub fn hash(&self) -> String {
        match self.fragment.as_deref() {
            None | Some("") => String::new(),
            Some(f) => format!("#{f}"),
        }
    }
    /// `searchParams`: the query parsed as application/x-www-form-urlencoded.
    pub fn search_params(&self) -> UrlSearchParams {
        UrlSearchParams::parse(self.query.as_deref().unwrap_or(""))
    }

    // ------------------------------------------------------------ §6.1 the URL API: setters

    /// `href` setter: a failure leaves the URL unchanged (the API throws a TypeError).
    pub fn set_href(&mut self, v: &str) -> Result<(), UrlError> {
        *self = Url::parse(v)?;
        Ok(())
    }

    /// `protocol` setter: `v` + `:` through the scheme start state.
    pub fn set_protocol(&mut self, v: &str) {
        let mut s = String::with_capacity(v.len() + 1);
        s.push_str(v);
        s.push(':');
        self.reparse(&s, State::SchemeStart);
    }

    /// `username` setter.
    pub fn set_username(&mut self, v: &str) {
        if self.cannot_have_username_password_port() {
            return;
        }
        self.username = percent_encode(v, EncodeSet::Userinfo);
    }

    /// `password` setter.
    pub fn set_password(&mut self, v: &str) {
        if self.cannot_have_username_password_port() {
            return;
        }
        self.password = percent_encode(v, EncodeSet::Userinfo);
    }

    /// `host` setter (host state override).
    pub fn set_host(&mut self, v: &str) {
        if self.has_opaque_path() {
            return;
        }
        self.reparse(v, State::Host);
    }

    /// `hostname` setter (hostname state override).
    pub fn set_hostname(&mut self, v: &str) {
        if self.has_opaque_path() {
            return;
        }
        self.reparse(v, State::Hostname);
    }

    /// `port` setter (port state override; the empty string removes the port).
    pub fn set_port(&mut self, v: &str) {
        if self.cannot_have_username_password_port() {
            return;
        }
        if v.is_empty() {
            self.port = None;
        } else {
            self.reparse(v, State::Port);
        }
    }

    /// `pathname` setter (the path is emptied, then path start state override).
    pub fn set_pathname(&mut self, v: &str) {
        if self.has_opaque_path() {
            return;
        }
        self.path = UrlPath::List(Vec::new());
        self.reparse(v, State::PathStart);
    }

    /// `search` setter (one leading `?` removed; the empty string removes the query).
    pub fn set_search(&mut self, v: &str) {
        if v.is_empty() {
            self.query = None;
            return;
        }
        let input = v.strip_prefix('?').unwrap_or(v);
        self.query = Some(String::new());
        self.reparse(input, State::Query);
    }

    /// `hash` setter (one leading `#` removed; the empty string removes the fragment).
    pub fn set_hash(&mut self, v: &str) {
        if v.is_empty() {
            self.fragment = None;
            return;
        }
        let input = v.strip_prefix('#').unwrap_or(v);
        self.fragment = Some(String::new());
        self.reparse(input, State::Fragment);
    }

    /// §6.2 the `URLSearchParams` update steps: the list serialized becomes the query (null when empty).
    pub fn set_search_params(&mut self, params: &UrlSearchParams) {
        let s = params.to_string();
        self.query = if s.is_empty() { None } else { Some(s) };
    }

    // ------------------------------------------------------------ serialization and origin

    /// The request-target of an HTTP request in origin-form (RFC 9112 §3.2.1): path + `?query`.
    pub fn request_target(&self) -> String {
        let mut t = self.pathname();
        if t.is_empty() {
            t.push('/');
        }
        if let Some(q) = &self.query {
            t.push('?');
            t.push_str(q);
        }
        t
    }

    /// §4.5 the URL serializer.
    pub fn serialize(&self, exclude_fragment: bool) -> String {
        let mut o = String::with_capacity(64);
        o.push_str(&self.scheme);
        o.push(':');
        if let Some(h) = &self.host {
            o.push_str("//");
            if self.includes_credentials() {
                o.push_str(&self.username);
                if !self.password.is_empty() {
                    o.push(':');
                    o.push_str(&self.password);
                }
                o.push('@');
            }
            o.push_str(&h.to_string());
            if let Some(p) = self.port {
                o.push(':');
                o.push_str(&p.to_string());
            }
        } else if let UrlPath::List(v) = &self.path {
            if v.len() > 1 && v[0].is_empty() {
                o.push_str("/.");
            }
        }
        o.push_str(&self.pathname());
        if let Some(q) = &self.query {
            o.push('?');
            o.push_str(q);
        }
        if !exclude_fragment {
            if let Some(f) = &self.fragment {
                o.push('#');
                o.push_str(f);
            }
        }
        o
    }

    /// §4.7 origin, serialized (HTML's serialization of an origin): `scheme://host[:port]`, or `"null"` for
    /// an opaque origin. A `blob:` URL takes the origin of the URL its path parses to when that is http(s)
    /// or file (a file origin is opaque here, as the standard leaves it to the implementation).
    pub fn origin(&self) -> String {
        match self.scheme.as_str() {
            "blob" => match Url::parse(&self.pathname()) {
                Ok(u) if u.scheme == "http" || u.scheme == "https" => u.origin(),
                _ => "null".into(),
            },
            "ftp" | "http" | "https" | "ws" | "wss" => format!("{}://{}", self.scheme, self.host_str()),
            _ => "null".into(),
        }
    }

    /// The origin is a tuple origin (not opaque).
    pub fn has_tuple_origin(&self) -> bool {
        self.origin() != "null"
    }

    /// Same origin (HTML §7.1.1): two tuple origins with equal scheme, host and port. An opaque origin is
    /// only ever same-origin with itself, which two separately parsed URLs never are.
    pub fn same_origin(&self, other: &Url) -> bool {
        let (a, b) = (self.origin_tuple(), other.origin_tuple());
        a.is_some() && a == b
    }

    fn origin_tuple(&self) -> Option<(String, Option<Host>, Option<u16>)> {
        match self.scheme.as_str() {
            "blob" => Url::parse(&self.pathname())
                .ok()
                .filter(|u| u.scheme == "http" || u.scheme == "https")
                .and_then(|u| u.origin_tuple()),
            "ftp" | "http" | "https" | "ws" | "wss" => Some((self.scheme.clone(), self.host.clone(), self.port)),
            _ => None,
        }
    }
}

impl fmt::Display for Url {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.href())
    }
}

impl core::str::FromStr for Url {
    type Err = UrlError;
    fn from_str(s: &str) -> Result<Url, UrlError> {
        Url::parse(s)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rfc3492_samples() {
        // RFC 3492 §7.1 (A) Arabic (Egyptian) and (L) 3<nen>B<gumi><kinpachi><sensei>.
        let arabic = "\u{0644}\u{064A}\u{0647}\u{0645}\u{0627}\u{0628}\u{062A}\u{0643}\u{0644}\u{0645}\u{0648}\u{0634}\u{0639}\u{0631}\u{0628}\u{064A}\u{061F}";
        assert_eq!(punycode_encode(arabic).unwrap(), "egbpdaj6bu4bxfgehfvwxn");
        assert_eq!(punycode_decode("egbpdaj6bu4bxfgehfvwxn").unwrap(), arabic);
        let l = "3\u{5E74}B\u{7D44}\u{91D1}\u{516B}\u{5148}\u{751F}";
        assert_eq!(punycode_encode(l).unwrap(), "3B-ww4c5e180e575a65lsy2b");
        assert_eq!(punycode_decode("3B-ww4c5e180e575a65lsy2b").unwrap(), l);
        assert_eq!(domain_to_ascii("b\u{FC}cher.de").unwrap(), "xn--bcher-kva.de");
        // NFC through the mapping: u + combining diaeresis composes to ü before Punycode.
        assert_eq!(domain_to_ascii("bu\u{308}cher.de").unwrap(), "xn--bcher-kva.de");
        // Nontransitional: ß stays (a deviation), fullwidth and ideographic full stop map.
        assert_eq!(domain_to_ascii("fa\u{DF}.de").unwrap(), "xn--fa-hia.de");
        assert_eq!(domain_to_ascii("\u{FF21}\u{3002}b").unwrap(), "a.b");
        // ContextJ: a bare ZWJ is refused; Bidi: a digit-first label in an RTL domain is refused.
        assert!(domain_to_ascii("a\u{200D}b").is_err());
        assert!(domain_to_ascii("1a.\u{5D0}").is_err());
    }

    #[test]
    fn basics() {
        let u = Url::parse("HTTPS://User:Pa ss@EXAMPLE.com:443/a/./b/../c?q=1 2#f g").unwrap();
        assert_eq!(u.href(), "https://User:Pa%20ss@example.com/a/c?q=1%202#f%20g");
        assert_eq!(u.origin(), "https://example.com");
        let b = Url::parse("http://a/b/c/d;p?q").unwrap();
        // RFC 3986 §5.4.1 normal examples.
        for (r, want) in [
            ("g", "http://a/b/c/g"),
            ("./g", "http://a/b/c/g"),
            ("g/", "http://a/b/c/g/"),
            ("/g", "http://a/g"),
            ("//g", "http://g/"),
            ("?y", "http://a/b/c/d;p?y"),
            ("g?y", "http://a/b/c/g?y"),
            ("#s", "http://a/b/c/d;p?q#s"),
            ("../..", "http://a/"),
            ("../../../g", "http://a/g"),
        ] {
            assert_eq!(b.join(r).unwrap().href(), want, "{r}");
        }
        assert_eq!(Url::parse("http://[::1]:8080/").unwrap().host_str(), "[::1]:8080");
        assert_eq!(Url::parse("http://0x7f.1/").unwrap().hostname(), "127.0.0.1");
        assert!(Url::parse("http://a b/").is_err());
    }

    #[test]
    fn setters() {
        let mut u = Url::parse("http://example.net/path").unwrap();
        u.set_host("example.com:8080stuff2");
        assert_eq!(u.href(), "http://example.com:8080/path");
        u.set_hostname("example.org:1");
        assert_eq!(u.href(), "http://example.com:8080/path");
        u.set_port("80");
        assert_eq!(u.href(), "http://example.com/path");
        u.set_protocol("b");
        assert_eq!(u.protocol(), "http:");
        u.set_protocol("https:foo");
        assert_eq!(u.href(), "https://example.com/path");
        u.set_pathname("/a b/../c");
        u.set_search("?x=1 2");
        u.set_hash("h");
        assert_eq!(u.href(), "https://example.com/c?x=1%202#h");
        u.set_username("u:x");
        assert_eq!(u.href(), "https://u%3Ax@example.com/c?x=1%202#h");
        let mut d = Url::parse("data:space  ?query#fragment").unwrap();
        d.set_search("");
        assert_eq!(d.href(), "data:space %20#fragment");
    }

    #[test]
    fn search_params() {
        let mut p = UrlSearchParams::parse("?a=1&b=hello+world&a=2&c=%F0%9F%92%A9");
        assert_eq!(p.get_all("a"), ["1", "2"]);
        assert_eq!(p.get("b"), Some("hello world"));
        assert_eq!(p.get("c"), Some("\u{1F4A9}"));
        p.set("a", "x y");
        p.delete("c", None);
        p.sort();
        assert_eq!(p.to_string(), "a=x+y&b=hello+world");
        let mut u = Url::parse("https://h/?q").unwrap();
        u.set_search_params(&p);
        assert_eq!(u.href(), "https://h/?a=x+y&b=hello+world");
        assert_eq!(form::byte_serialize("q=hello world & rust~".as_bytes()), "q%3Dhello+world+%26+rust%7E");
    }
}
